from oct11_seo_bodies._html import assemble, related


def body() -> str:
    return assemble(
        intro="Spicy meals, nuts, and seeds dominate IBD trigger lists online. Crohn's disease and ulcerative colitis patients ask whether capsaicin, peanut butter, or whole seeds are safe. This page covers tolerance trials, stricture caution, and the difference between symptom irritation and inflammation. Education only.",
        sections=[('Why spice and crunch questions persist', ['Capsaicin can speed transit or burn inflamed rectums in some ulcerative colitis patients.', 'Whole nuts and seeds add mechanical load that narrowed segments dislike.', 'Social media absolutes ignore remission versus flare context.', 'Trials beat forever bans when teams agree inflammation is controlled.']), ('Spicy foods and symptom pathways', ['Mild spice in remission may be fine while active proctitis prefers bland oils and herbs.', 'Hot chili sauces hide garlic and onion fermentables that confuse FODMAP trials.', 'Separate spice tests from sauce tests when logging.', 'Rectal burning after meals deserves mention even without visible blood.']), ('Nuts versus nut butters', ['Smooth peanut or almond butter spreads reduce mechanical load compared with whole nuts.', 'Fat content still matters; large spoonfuls may speed urgency for some people.', 'Trial one teaspoon on a safe starch before sandwiches full of butter.', 'Salted varieties affect hydration; read labels.']), ('Seeds, popcorn, and strictures', ["Stricturing Crohn's patients should ask explicitly before crunch heavy snacks.", 'Popcorn combines insoluble fiber and sharp hulls many teams pause during stricture worry.', 'Obstructive symptoms such as vomiting with bloating need urgent evaluation, not more fiber experiments.', 'Imaging history guides crunch more than generic internet seed bans.']), ('Trial method clinicians prefer', ['Change one variable at a time with a small portion and log 48 hours.', 'Stop if pain, vomiting, or nocturnal stools rise.', 'Retry in remission only after team agrees inflammation is quiet.', 'Children need choking safety considered separately from IBD tolerance.']), ('Nutrition upside when tolerated', ['Nuts offer calories, protein, and unsaturated fats helpful for weight maintenance.', 'Spices like turmeric in food amounts differ from high dose supplement hype.', 'Sprinkle ground seeds on yogurt may fit when whole seeds do not.', "Calorie dense foods help some underweight Crohn's patients in remission."]), ('Restaurant and cultural meals', ['Ask for sauce on side, choose mild curries, swap whole nut garnishes for smooth sauces when testing.', 'Explain needs without apologizing; kitchens often adjust heat.', 'Buffets hide mixed oils; small plates reduce accidental triggers.', 'Travel packs of safe nut butter help when airline meals are unknown.']), ('School policies versus medical texture', ['Allergy free classrooms may ban peanuts while medically you trial almond butter at home.', 'Separate school policy letters from gastroenterology advice.', '504 plans can clarify bathroom access unrelated to nut rules.', 'Teachers appreciate simple safe snack lists.']), ('Flare versus remission rules of thumb', ['Flares often favor bland proteins, low fiber textures, and paused crunch.', 'Remission reintroduction might start with smooth nut butter before whole cashews.', 'Spice may return last after oil and fiber trials succeed.', 'Calprotectin trends should guide timing more than calendar ego.']), ('Ostomy and output considerations', ['High fat nut loads may increase output volume for some ostomates.', 'Empty appliances before spice experiments when output is unpredictable.', 'Hydration rises when output loosens after curry nights.', 'Skin care remains priority when output acidity changes.']), ('Allergy testing confusion', ['Positive skin tests to foods you tolerate clinically should be interpreted with allergists.', 'Do not eliminate wide groups based on panels alone without IBD context.', 'Oral allergy syndrome from pollen cross reactivity differs from IBD decisions.', 'Bring both allergy and GI notes to combined visits when possible.']), ('Supplement powders and nut flours', ['Almond flour baked goods concentrate fat and calories; portion size still matters.', 'Chia and flax gel may soothe some constipated patients yet worsen diarrhea predominant patterns.', 'Protein powders with nut flavors may include artificial sweeteners that stir stools.', 'Read ingredient lists for sugar alcohols during trials.']), ('When spice or nuts are the wrong focus', ['Active inflammation may need medicines before any trigger hunt.', 'Bile acid diarrhea mimics food triggers; clinicians test separately.', 'Infection or C diff recurrence deserves testing when symptoms change abruptly.', 'Do not delay scope or stool studies because a blogger blamed chili.']), ('Logging and clinic follow up', ['Record brand, portion, preparation, and symptoms in IBDPal for two days after trials.', 'Bring logs to dietitians instead of memory alone.', 'Celebrate successful reintroductions without labeling yourself cured.', 'Failed trials still provide useful data for the next plan.']), ('Capsaicin creams versus spicy meals', ['Topical capsaicin for arthritis differs from eating chili; do not conflate skin and gut trials.', 'Wash hands after handling hot peppers before touching eyes or ostomy appliances.', 'Garden grown peppers vary heat; label home jars with mild or hot stickers.', 'Gloves help prep night when rectal disease is active.']), ('Tree nuts, peanuts, and cross reactivity', ['Peanuts are legumes; tree nuts are separate biologically yet both get lumped online.', 'Trial one nut type at a time if allergy testing was negative clinically.', 'Mixed nut bags blur results; buy single nut jars for clarity.', 'Nut flours in gluten free baking concentrate calories quickly.']), ('Spice blends and hidden triggers', ['Curry powder may include garlic, onion, or chili in ratios you cannot taste separately.', 'BBQ rubs often hide sugar and salt loads.', 'Request ingredient lists at restaurants when testing spice not sugar.', 'Homemade blends let you control heat stepwise.']), ('Pouchitis and rectal heat sensitivity', ['J pouch patients may feel spice as urgency even when small bowel tolerates heat.', 'Track pouchitis flares separately from spice trials.', 'Cooling sides like cucumber yogurt may pair with mild mains if tolerated.', 'Surgeon input matters before aggressive spice challenges post op.']), ('Weight gain and calorie dense nuts', ["Underweight Crohn's patients may welcome nut calories in remission.", 'Portion cups prevent mindless handfuls during TV nights.', 'Combine nut butter with banana on rice cakes for dense snacks.', 'Monitor LDL if cardiovascular risk exists alongside IBD.']), ('Fiber loading mistakes after remission', ['Reintroducing whole nuts and raw veggies simultaneously blames the wrong food.', 'Sequence crunch after cooked fiber succeeds.', 'Popcorn trials wait until stricture imaging is recent.', 'Celebrate intermediate wins like smooth nut butter before whole almonds.']), ('Cultural stigma around bland diets', ['Family may view bland food as sadness; explain temporary medical texture phases.', 'Offer to cook mild base dish others can spice separately.', 'Food culture identity matters; work with dietitians on culturally familiar legal foods.', 'Language interpreters help explain trials at multilingual family tables.']), ('Emergency symptoms versus trial failure', ['Vomiting with abdominal distension stops trials and triggers urgent calls.', 'Blood after crunch trials differs from streaks you already reported to GI.', 'Night sweats and fever with pain suggest infection not spice.', 'Keep trial portions tiny enough that failure is inconvenient not dangerous.']), ('Heat scale experiments', ['Start with mild paprika on home potatoes before ghost pepper sauces.', 'Keep dairy free cooling sides ready if capsaicin trial fails.', 'Note whether oil based spice carries heat differently than dry rubs.', 'Stop at tingling lips if oral allergy syndrome coexists.']), ('Nut roasting at home', ['Dry roast small almond batches to control salt and oil compared with store cans.', 'Burned nuts irritate guts and taste awful; timer reminders help distracted cooks.', 'Let nuts cool before eating to avoid mouth burns masking gut feedback.', 'Store roasted nuts sealed so rancidity does not mimic flare symptoms.']), ('Seed grinders and texture', ['Coffee grinders dedicated to flax or chia create smoother textures than whole seeds.', 'Start with half teaspoon ground seed on oatmeal trials.', 'Clean grinder between allergens if household has peanut allergy.', 'Discard old ground seed jars after trial month ends.']), ('Reading menu language', ['Words like Nashville hot or volcanic signal heat beyond mild.', 'Ask whether chili paste is in kimchi or mapo tofu before ordering.', 'Ethnic markets label spice levels inconsistently; ask shop owners politely.', 'Takeout spice often intensifies overnight in fridge; reheat small test portion.']), ('Combining spice trials with alcohol', ['Bar wings plus beer stack triggers for many; isolate variables sober first.', 'Happy hour spice may blur next day flare attribution.', 'Designated drivers still deserve tolerated snacks at events.', 'Log alcohol and spice on same IBDPal entry when both occur.']), ('Teaching kids spice curiosity safely', ['Pediatric IBD spice trials need smaller portions and choking aware textures.', 'School lunches may avoid nuts entirely; home trials differ.', 'Praise kids for stopping when belly says no.', 'Keep epinephrine plans separate from IBD tolerance if true allergy exists.']), ('Shopping aisle strategy', ['Read nut butters labels for added palm oil or sugar alcohols before buying large jars.', 'Single serve nut butter packets reduce waste when trials fail early.', 'Bulk spice bins risk cross contact; choose sealed bottles when allergy or strictures matter.', 'Store opened nut flours in fridge to prevent rancid taste mimicking flare.']), ('Picnic and barbecue season', ['Potluck chili labels should list heat level and nut garnishes separately.', 'Bring your own bun and patty if cross contact with seeds worries you.', 'Grill brushes leaving wire bristles are rare but serious; inspect plates.', 'Ice packs keep nut butter sandwiches safe in summer heat.']), ('Texture modification tools', ['Food processors turn whole nuts into pastes for baking trials.', 'Silicone mats help roast vegetables with spice blends without sticking burns.', 'Slow cookers soften tough meats with mild spice when chewing is limited.', 'Immersion blenders smooth soups after failed crunch experiments.']), ('Follow up after failed spice trial', ['Note which meal, sleep quality, and stress level surrounded the failure.', 'Wait until inflammation labs quiet before repeating heat tests.', 'Try different cuisine spice profiles; capsaicin is not the only irritant.', 'Share failed trial data with dietitian to plan next variable.']), ('Closing planning notes for your next clinic visit', ['Print or bookmark the sections that matched your week, cross out what did not, and bring one page of questions instead of relying on memory in a rushed appointment.', 'Ask for written flare and remission targets so home experiments stay aligned with scope results, calprotectin trends, and the medicine plan you already follow.', 'If a paragraph felt confusing, note the heading in your portal message so clinicians know exactly where you need clearer guidance rather than a vague request for help.', 'Small steady steps beat dramatic overhauls that collapse after three days; consistency of logging and follow up usually matters more than perfect adherence to internet lists.']), ('One sentence to remember', ['Spice and crunch trials are data collection tools, not loyalty tests to any online food tribe.']), ('Meal prep when testing crunch and heat separately', ['Cook base chicken or tofu plain, then split portions into mild and spicy plates for same dinner.', 'Add ground seeds only to one rice bowl so comparison stays fair.', 'Label containers MILD and TEST in fridge to prevent sleepy grabbing mistakes.', 'Freeze untested portions if appetite drops mid week.'])],
        clinic_quote='Do I have strictures or active proctitis that should limit whole nuts, seeds, or spicy foods? If a trial is OK, what portion and preparation style should I start with?',
        faqs=[('Are seeds always forbidden?', 'Old diverticulosis myths do not automatically apply to IBD. Individualize with imaging and symptoms.'), ('Is almond flour safer than whole almonds?', 'Often yes for texture; fat load still matters.'), ('Does spicy food cause inflammation?', 'Spice usually irritates symptoms for some; it does not replace treating mucosal inflammation with meds.'), ('Can children with IBD eat nuts?', 'Ask pediatrics about texture, choking, and allergy policy together.')],
        related_html=related(
            ("Flare foods", "/blog/flare-foods-ibd"),
            ("Low residue ideas", "/blog/low-residue-diet-ibd"),
            ("Fiber overview", "/blog/fiber-ibd-flare-remission"),
            ("IBD nutrition hub", "/ibd-nutrition"),
        ),
        closing=['Spice and crunch are experiments, not morality tests. Let data and clinicians guide reintroduction.'],
    )
